// el az de mentira lanzado con Node: en Windows un guion de bash sin extensión no se puede lanzar directo
const path = require('path');
const r = require('child_process').spawnSync(process.env.CLAUDE_CODE_GIT_BASH_PATH || 'bash', [path.join(__dirname, 'az', 'az'), ...process.argv.slice(2)], { stdio: 'inherit' });
process.exit(r.status === null ? 1 : r.status);

